# Round 4: distinct country pages, regional merges, rebuilt contact pages.
from common import *
import re
NAV=[('/meta-appeal-links-and-forms-directory/','Meta appeal links'),('/how-to-contact-meta-about-a-disabled-account/','How to contact Meta'),('/account-recovery-by-country/','Account recovery by country'),('/pricing/','Pricing')]
OFF=('<p>The Meta routes themselves do not change by country: appeal from the notice you see at login (or in Accounts Center), use '+ext('https://www.instagram.com/hacked/')+' or '+ext('https://www.facebook.com/hacked')+' for a takeover, and ask for ad account reviews in '+ext('https://business.facebook.com/accountquality')+'. The full list is in the '+a('/meta-appeal-links-and-forms-directory/','Meta appeal links directory')+'. What follows is only what differs here.</p>')
def R(*rows): return linkrows(list(rows))
ACE=('Appeals Centre Europe','https://www.appealscentre.eu/','Certified by Coimisiún na Meán. Reviews account suspensions and Page or Group removals on Facebook and Instagram after Meta’s own appeal, for users in any EU country.')
UR=('User Rights','https://www.user-rights.org/en','Certified by Germany’s Bundesnetzagentur. Handles Facebook and Instagram moderation disputes in German, English, French and Italian.')
ADR=('ADR Center','https://ods.adrcenter.com/en/','Certified by Italy’s AGCOM in December 2024, including disputes over access to the platform, in many EU languages.')
D={}
def C(slug,**k): D[slug]=k
# ---------------- standalone countries ----------------
C('usa',n='the US',N='the USA',tz='Pacific Time is Meta’s home time zone (Menlo Park, California)',
 ans='There is no federal data-protection regulator in the US, so the practical escalations are the FTC for fake “Meta support” scams, the FBI’s IC3 for hacking with money lost, and state privacy laws such as California’s CCPA for getting a copy of your data.',
 cards=[('FTC + IC3','Scams and hacking with money lost.'),('State privacy laws','CCPA access requests in California.'),('TAKE IT DOWN Act','48-hour removal of intimate images.')],
 secs=[('regulators','Who to report to in the US',R(('FTC ReportFraud','https://reportfraud.ftc.gov/','Report fake Meta or Instagram “support” agents, recovery scams and impersonation. The FTC uses reports for enforcement; it does not restore accounts.'),('FBI Internet Crime Complaint Center (IC3)','https://www.ic3.gov/','For hacking, sextortion and fraud where money or crypto was lost. Keep the IC3 complaint number for your hacked-account appeal.'),('IdentityTheft.gov','https://www.identitytheft.gov/','If the hacker used your identity elsewhere, this builds a personal recovery plan.'),('California Privacy Protection Agency','https://cppa.ca.gov/','Enforces the CCPA. California residents can ask Meta what personal data it holds and complain here if a request is ignored.'),('NCMEC CyberTipline and Take It Down','https://takeitdown.ncmec.org/','For sexual images of anyone under 18, including images of yourself when you were a minor.'))),
  ('privacy','Getting your data from Meta in the US',f'<p>The US has no single GDPR-style law. Residents of states with comprehensive privacy laws, starting with California (CCPA as amended by the CPRA) and followed by states such as Virginia, Colorado, Connecticut and Texas, can ask a company for the personal data it holds. For a disabled account, Meta’s “Download your information” is often blocked, so a written access request is the alternative. It will not reverse the decision, but it can show which data and notices exist.</p>'),
  ('take-it-down','Intimate images: the TAKE IT DOWN Act','<p>Signed in May 2025, the federal TAKE IT DOWN Act requires covered platforms to remove reported non-consensual intimate images, including AI-generated ones, within 48 hours of a valid request, with compliance due from May 2026. If someone posted such images of you on Instagram or Facebook, report them through Meta’s in-app tools first and keep the report confirmation.</p>'),
  ('us-issues','Common US situations we see',ul(['Search ads and Instagram comments advertising a “Meta support” phone number: all fake. Report them to the FTC.','Small businesses losing the ad account and Page together after a Business Portfolio admin is hacked.','Accounts disabled for “child sexual exploitation” on a single misread photo; see '+a('/facebook-disabled-child-sexual-exploitation-policy/','that notice explained')+'.'])),
  ('timing','Time zones and timing','<p>Meta is headquartered in Menlo Park, California, but appeals are reviewed by teams worldwide, so the time of day you send an appeal does not matter. Submit once and wait; repeat submissions do not move you up a queue.</p>')],
 faqs=[('Is there a Meta support phone number in the US?','No public number for account help. Numbers in search ads are scams; report them at reportfraud.ftc.gov.'),('Should I file with IC3 for a hacked Instagram account?','Yes, if money, crypto or extortion is involved. Keep the complaint number.'),('Does the CCPA force Meta to restore my account?','No. It gives California residents access and deletion rights over data, not a right to an account.')])
C('uk',n='the UK',N='the UK',
 ans='In the UK, the escalations are the ICO for data requests Meta ignores, Report Fraud (which replaced Action Fraud on 4 December 2025) for hacking and scams, and the Online Safety Act framework that Ofcom enforces, although Ofcom does not handle individual complaints.',
 cards=[('ICO','Subject access requests: one month.'),('Report Fraud','Replaced Action Fraud, Dec 2025.'),('Online Safety Act','Ofcom regulates; no individual cases.')],
 secs=[('regulators','Who to report to in the UK',R(('Information Commissioner’s Office (ICO)','https://ico.org.uk/make-a-complaint/','Raise the issue with Meta first; if it does not respond properly, complain to the ICO.'),('Report Fraud','https://www.reportfraud.police.uk/','The City of London Police service for fraud and cybercrime in England, Wales and Northern Ireland, including hacked social media accounts. Phone 0300 123 2040.'),('Police Scotland','https://www.scotland.police.uk/','In Scotland, report fraud and hacking on 101 instead.'),('Report Harmful Content','https://reportharmfulcontent.com/','A national service run by SWGfL that helps when platforms do not act on harmful content you reported.'),('Revenge Porn Helpline / StopNCII','https://stopncii.org/','For intimate images shared or threatened without consent.'))),
  ('sar','Subject access request under UK GDPR','<p>Under the UK GDPR and the Data Protection Act 2018 you can ask Meta for a copy of the personal data it holds about you, including records linked to an account decision. The normal deadline is one calendar month, extendable by two further months for complex requests. If the reply is missing or incomplete, the ICO is the next step. A SAR does not reinstate an account, but it can show what Meta relied on.</p>'),
  ('osa','The Online Safety Act and Ofcom','<p>Ofcom enforces the Online Safety Act 2023, which requires services such as Instagram and Facebook to run complaints procedures, including for users who think content was wrongly taken down. Ofcom does not decide individual cases, so it will not restore your account, but it collects complaints to spot systemic failures. Write to Meta through the in-app appeal first.</p>'),
  ('uk-issues','Common UK situations',ul(['Hacked accounts used to run fake ticket or crypto offers to your followers. Get a Report Fraud reference before you appeal.','Under-18 accounts placed into Teen Account settings and adults wrongly flagged as teens after an age check.','Sole traders whose Instagram shop and ad account are restricted together.'])),
  ('timing','Timing','<p>The UK is on GMT in winter and BST in summer. Reviews run worldwide, so submission time does not matter; what matters is sending one complete appeal.</p>')],
 faqs=[('Is Action Fraud still the place to report?','No. Since 4 December 2025, Report Fraud has replaced Action Fraud in England, Wales and Northern Ireland. In Scotland, call Police Scotland on 101.'),('How long does Meta have to answer a subject access request?','One month, extendable by up to two more months for complex requests.'),('Can Ofcom get my Instagram back?','No. Ofcom regulates systems and does not handle individual account cases.')])
C('canada',n='Canada',N='Canada',
 ans='In Canada, the Office of the Privacy Commissioner handles complaints when Meta ignores an access request under PIPEDA, Quebec residents also have the Commission d’accès à l’information under Law 25, and the Canadian Anti-Fraud Centre takes reports of fake support scams. Canada has no online safety regulator yet.',
 cards=[('OPC / PIPEDA','30 days to answer an access request.'),('Quebec Law 25','Commission d’accès à l’information.'),('Anti-Fraud Centre','1-888-495-8501.')],
 secs=[('regulators','Who to report to in Canada',R(('Office of the Privacy Commissioner of Canada','https://www.priv.gc.ca/en/report-a-concern/','Complaints about how a company handles your personal information, including unanswered access requests.'),('Commission d’accès à l’information du Québec','https://www.cai.gouv.qc.ca/','Quebec’s regulator under Law 25, for Quebec residents.'),('Canadian Anti-Fraud Centre','https://antifraudcentre-centreantifraude.ca/','Report recovery scams and fake “Meta agents” online or at 1-888-495-8501.'),('Cybertip.ca','https://www.cybertip.ca/','The national tipline for online sexual exploitation of children, run by the Canadian Centre for Child Protection.'),('NeedHelpNow.ca','https://needhelpnow.ca/','For teens whose intimate images were shared.'))),
  ('pipeda','Access requests under PIPEDA','<p>PIPEDA lets you ask an organisation for the personal information it holds about you. It must normally respond within 30 days. If Meta refuses or ignores the request, you can complain to the OPC. The OPC cannot order an account back, but it can investigate how your data was handled.</p>'),
  ('online-harms','No online safety regulator yet','<p>The federal Online Harms Act (Bill C-63) would have created a Digital Safety Commission, but it died when Parliament was prorogued in January 2025. For now, Meta’s own appeal is the only route to reverse a disable, and police or the Anti-Fraud Centre handle crimes.</p>'),
  ('language','English or French','<p>Meta reviews appeals in both official languages. Quebec users who think in French should appeal in French; precision beats translation. Our '+a('/fr/liens-officiels-appel-meta-instagram-facebook/','French guide')+' covers the same routes.</p>'),
  ('timing','Time zones','<p>Canada spans six time zones, from Newfoundland to Pacific. It makes no difference to Meta’s review queue; send one complete appeal.</p>')],
 faqs=[('Is there a Meta phone number in Canada?','No support line for accounts. Report fake numbers to the Canadian Anti-Fraud Centre.'),('Can the Privacy Commissioner restore my account?','No. The OPC handles privacy complaints, not account decisions.'),('Should I appeal in French?','If French is your strongest language, yes.')])
C('australia',n='Australia',N='Australia',
 ans='In Australia, eSafety can act on serious cyber abuse and image-based abuse once you have reported it to Meta, the OAIC handles privacy complaints after a 30-day wait for Meta’s reply, and since 10 December 2025 Instagram and Facebook must keep under-16s off the platforms.',
 cards=[('eSafety','After you report to Meta first.'),('OAIC','Complain after 30 days.'),('Under-16 ban','In force since 10 Dec 2025.')],
 secs=[('regulators','Who to report to in Australia',R(('eSafety Commissioner','https://www.esafety.gov.au/report','Adult cyber abuse, cyberbullying of under-18s, image-based abuse and illegal content. You must report to the platform first and keep the report reference.'),('OAIC','https://www.oaic.gov.au/privacy/privacy-complaints','Privacy complaints under the Privacy Act 1988. Complain to Meta first and allow 30 days.'),('ReportCyber','https://www.cyber.gov.au/report-and-recover','The Australian Signals Directorate’s service for reporting hacking and cybercrime.'),('Scamwatch','https://www.scamwatch.gov.au/','The ACCC’s scam reporting site, for fake “Meta support” offers.'),('IDCARE','https://www.idcare.org/','Free identity and cyber support if the hacker used your identity.'))),
  ('under-16','The social media minimum age (under-16 ban)','<p>Under the Online Safety Amendment (Social Media Minimum Age) Act, Instagram and Facebook must take reasonable steps to stop Australians under 16 from holding accounts from 10 December 2025. Meta began deactivating affected accounts in early December 2025. If you are 16 or older and were wrongly flagged, Meta’s process lets you prove your age with a video selfie age check or government ID. Under-16s and parents are not fined; platforms are.</p>'),
  ('esafety-how','How an eSafety complaint works','<p>Collect evidence first: screenshots, URLs and the profile involved. Report the content to Meta, then, if it meets the legal threshold and Meta does not act, report to eSafety with the Meta report reference. eSafety can direct removal of seriously harmful content. It does not reinstate disabled accounts.</p>'),
  ('timing','Time zones','<p>Australia runs AEST/AEDT, ACST and AWST. Meta reviews globally, so overnight submission does not help or hurt.</p>')],
 faqs=[('My 17-year-old’s account was deactivated as under 16. What now?','Use the age-check option in the notice (video selfie or ID).'),('Can eSafety get my disabled account back?','No. eSafety handles harmful content, not account decisions.'),('When can I complain to the OAIC?','After complaining to Meta and allowing 30 days for a reply.')])
C('new-zealand',n='New Zealand',N='New Zealand',
 ans='In New Zealand, Netsafe is the approved agency under the Harmful Digital Communications Act and the most practical first stop for harassment, impersonation and hacked accounts; the Privacy Commissioner handles data complaints, and agencies must answer access requests within 20 working days.',
 cards=[('Netsafe','Approved agency under the HDCA.'),('Privacy Act 2020','20 working days for access.'),('Scam texts','Forward to 7726.')],
 secs=[('regulators','Who to contact in New Zealand',R(('Netsafe','https://netsafe.org.nz/','Free, independent online safety service. Can liaise with platforms on harmful digital communications.'),('Office of the Privacy Commissioner','https://www.privacy.org.nz/','Privacy complaints and guidance on access requests.'),('NCSC New Zealand','https://www.ncsc.govt.nz/','Report hacking and scams (CERT NZ became part of the NCSC).'),('Department of Internal Affairs: 7726','https://www.dia.govt.nz/','Forward scam texts free to 7726.'))),
  ('hdca','The Harmful Digital Communications Act','<p>Under the HDCA 2015, Netsafe receives complaints about harmful digital communications and tries to resolve them, often by contacting the platform. If that fails, you can apply to the District Court for orders such as takedown. This route is for harassment and impersonation, not for a disabled account.</p>'),
  ('privacy','Your data under the Privacy Act 2020','<p>You can ask any agency, including overseas ones doing business in New Zealand, for personal information it holds about you. Agencies must respond within 20 working days. If Meta ignores you, complain to the Privacy Commissioner.</p>'),
  ('language','Language','<p>Appeal in English or te reo Māori, whichever is more precise for you.</p>')],
 faqs=[('Can Netsafe restore my Instagram?','Netsafe can contact platforms about harmful content, but it cannot overrule a disable decision.'),('How long does an access request take?','Up to 20 working days.')])
C('ireland',n='Ireland',N='Ireland',eu=True,
 ans='Ireland matters for every EU user because Meta Platforms Ireland is Meta’s EU provider: the Data Protection Commission is Meta’s lead EU data regulator, Coimisiún na Meán is the Digital Services Coordinator, and Appeals Centre Europe is a Dublin-based dispute body you can use after Meta’s own appeal.',
 cards=[('DPC','Lead EU data regulator for Meta.'),('Coimisiún na Meán','DSA coordinator, Online Safety Code.'),('ACE + IDR','Irish dispute bodies.')],
 secs=[('regulators','Irish bodies',R(('Data Protection Commission','https://www.dataprotection.ie/','Lead supervisory authority for Meta under the GDPR one-stop-shop. Takes complaints when Meta mishandles an access request.'),('Coimisiún na Meán','https://www.cnam.ie/','Digital Services Coordinator and online safety regulator; enforces the Online Safety Code for video-sharing platforms including Facebook and Instagram.'),ACE,('Impress Dispute Resolutions','https://www.cnam.ie/industry-and-professionals/online-safety-framework/certifications-schemes/out-of-court-dispute-settlement-bodies/','Certified in May 2026 for disputes about specific categories of illegal content, in English, accepting cases from August 2026.'),('Hotline.ie','https://hotline.ie/','Report child sexual abuse material and intimate image abuse.'),('An Garda Síochána','https://www.garda.ie/','Report hacking, fraud and extortion.'))),
  ('dsa','Statement of reasons and out-of-court appeal','<p>Under the Digital Services Act, Meta must tell you why it restricted your account (the statement of reasons) and give you an internal appeal. If that fails, you can take the decision to a certified body such as Appeals Centre Europe, which reviews account suspensions and Page or Group removals. See '+a('/appeals-centre-europe-instagram-facebook-suspension/','Appeals Centre Europe for Instagram and Facebook')+'.</p>'),
  ('coco','Intimate image abuse and Coco’s Law','<p>Sharing or threatening to share intimate images without consent is a criminal offence in Ireland under the Harassment, Harmful Communications and Related Offences Act 2020, known as Coco’s Law. Report to Hotline.ie and the Gardaí, and to Meta in the app.</p>'),
  ('access','Access requests','<p>Write to Meta Platforms Ireland for a copy of your data under the GDPR. It must reply within one month, extendable by two months. If it does not, complain to the DPC.</p>')],
 faqs=[('Why is Ireland so important for Meta appeals?','Meta Platforms Ireland is the provider for EU users, so Irish regulators lead on many Meta matters.'),('Do I have to go through Meta first?','Yes. Dispute bodies such as ACE review a decision after Meta’s internal appeal.'),('Can the DPC unban me?','No. It handles data protection, not moderation decisions.')])
C('germany',n='Germany',N='Germany',eu=True,lang=('/de/meta-einspruch-links-instagram-facebook/','Deutsch'),
 ans='In Germany, the Bundesnetzagentur is the Digital Services Coordinator, User Rights is a Berlin-based dispute body certified by it for Instagram and Facebook cases, and the Federal Court of Justice ruled in 2021 that Facebook must inform users and let them respond before blocking accounts over posts.',
 cards=[('Bundesnetzagentur','DSA complaints portal.'),('User Rights','Certified dispute body.'),('BGH 2021','Right to be heard before blocks.')],
 secs=[('regulators','German bodies',R(('Digital Services Coordinator (Bundesnetzagentur)','https://www.dsc.bund.de/','Complaints about platforms breaking DSA duties, such as missing statements of reasons.'),UR,ACE,('Your state data protection authority or the BfDI','https://www.bfdi.bund.de/','You can lodge a GDPR complaint locally; cases about Meta are coordinated with the Irish DPC.'),('HateAid','https://hateaid.org/','Advice for victims of digital violence and hate.'),('Polizei Onlinewache','https://www.polizei.de/','Each state’s online police station for hacking, fraud and extortion.'))),
  ('bgh','The 2021 Federal Court of Justice rulings','<p>In July 2021 the Bundesgerichtshof ruled (III ZR 179/20 and III ZR 192/20) that Facebook’s terms were invalid where they let it remove posts and block accounts without informing the user afterwards, and before an account block, giving a chance to respond. German users still cite these rulings in appeals and in court.</p>'),
  ('ods','Choosing a dispute body','<p>User Rights decides on German or EU law and on platform terms, and communicates in German, English, French and Italian. Appeals Centre Europe reviews against Meta’s own policies. You may pick either body once Meta’s internal appeal is done.</p>'),
  ('language','Auf Deutsch','<p>Write the appeal in German if that is your strongest language. Our '+a('/de/meta-einspruch-links-instagram-facebook/','German guide to Meta appeal links')+' covers the same routes.</p>')],
 faqs=[('Do I have to accept a Facebook block without explanation?','No. The DSA requires a statement of reasons, and German case law adds a right to be heard.'),('Which dispute body should I use in Germany?','User Rights or Appeals Centre Europe; both handle Facebook and Instagram.')])
C('france',n='France',N='France',eu=True,lang=('/fr/liens-officiels-appel-meta-instagram-facebook/','Français'),
 ans='In France, Arcom is the Digital Services Coordinator, the CNIL handles data complaints, 17Cyber is the government’s one-stop help service for hacked accounts and online scams, and Appeals Centre Europe and User Rights both work in French.',
 cards=[('Arcom','DSA coordinator.'),('17Cyber','Help for hacked accounts.'),('3018','Cyberbullying line for young people.')],
 secs=[('regulators','French bodies',R(('Arcom','https://www.arcom.fr/','France’s Digital Services Coordinator and media regulator.'),('CNIL','https://www.cnil.fr/fr/plaintes','Data protection complaints, including unanswered access requests.'),('17Cyber','https://www.17cyber.gouv.fr/','Government diagnostic and help service for hacking and online scams, linked to the police and gendarmerie.'),('Pharos','https://www.internet-signalement.gouv.fr/','Report illegal online content.'),('3018 (e-Enfance)','https://e-enfance.org/','Free line for young people facing cyberbullying or image sharing.'),ACE,UR)),
  ('language','Appealing in French','<p>Meta’s notices for French users are often in English, but you can write the appeal in French. Appeals Centre Europe and User Rights both communicate in French. Our '+a('/fr/liens-officiels-appel-meta-instagram-facebook/','French guide')+' lists the routes.</p>'),
  ('complaint','Before filing with Arcom or the CNIL','<p>Arcom looks at systemic DSA compliance and will not handle one account. The CNIL deals with data: ask Meta for your data first, then complain if it does not reply within one month.</p>')],
 faqs=[('Does Meta answer appeals in French?','Yes, appeals in French are reviewed.'),('Is 17Cyber useful for a hacked Instagram?','Yes, for diagnosis and filing a report.')])
C('netherlands',n='the Netherlands',N='the Netherlands',eu=True,lang=('/nl/officiele-bezwaarlinks-meta-instagram-facebook/','Nederlands'),
 ans='In the Netherlands, the ACM is the Digital Services Coordinator, the Autoriteit Persoonsgegevens takes data complaints, the Fraudehelpdesk handles scams, and a police report (aangifte) helps a hacked-account appeal when the hacker used the account for fraud.',
 cards=[('ACM','DSA coordinator.'),('Aangifte','Police report for hacking.'),('Helpwanted','Online sexual abuse help.')],
 secs=[('regulators','Dutch bodies',R(('ACM','https://www.acm.nl/','Digital Services Coordinator.'),('Autoriteit Persoonsgegevens','https://www.autoriteitpersoonsgegevens.nl/','Data protection complaints.'),('Fraudehelpdesk','https://www.fraudehelpdesk.nl/','Report fraud and phishing, including WhatsApp and Instagram scams.'),('Politie: aangifte doen','https://www.politie.nl/aangifte-of-melding-doen','File a report for hacking or fraud.'),('Helpwanted.nl','https://www.helpwanted.nl/','Support with sexual images shared online.'),ACE)),
  ('aangifte','Why an aangifte helps','<p>When a hacker used your account to sell fake products or ask friends for money, a police report number shows Meta the account was taken over. Mention it in the hacked-account form or appeal.</p>'),
  ('language','In het Nederlands','<p>Appeals Centre Europe communicates in Dutch. Our '+a('/nl/officiele-bezwaarlinks-meta-instagram-facebook/','Dutch guide')+' has the routes.</p>')],
 faqs=[('Can I appeal in Dutch?','Yes. Meta and Appeals Centre Europe both accept Dutch.'),('Should I file an aangifte for a hacked Instagram?','If it was used for fraud, yes.')])
C('spain',n='Spain',N='Spain',eu=True,lang=('/es/enlaces-oficiales-apelacion-meta-instagram-facebook/','Español'),
 ans='In Spain, INCIBE’s free 017 helpline helps with hacked accounts, the AEPD runs a priority channel for urgent removal of sexual or violent content, the CNMC is the Digital Services Coordinator, and Appeals Centre Europe works in Spanish.',
 cards=[('017','INCIBE cybersecurity helpline.'),('AEPD Canal Prioritario','Urgent removal of sensitive images.'),('CNMC','DSA coordinator.')],
 secs=[('regulators','Spanish bodies',R(('INCIBE: 017','https://www.incibe.es/linea-de-ayuda-en-ciberseguridad','Free, confidential cybersecurity helpline for hacked accounts and scams.'),('AEPD Canal Prioritario','https://www.aepd.es/canalprioritario','For sexual or violent content published without consent; the AEPD can order urgent removal.'),('AEPD','https://www.aepd.es/','Data protection complaints.'),('CNMC','https://www.cnmc.es/','Digital Services Coordinator.'),('Policía Nacional / Guardia Civil','https://www.policia.es/','Report hacking and online fraud.'),ACE,ADR)),
  ('language','En español','<p>ACE and ADR Center both work in Spanish. Our '+a('/es/enlaces-oficiales-apelacion-meta-instagram-facebook/','Spanish guide')+' covers the same routes. Catalan, Basque or Galician speakers can appeal to Meta in Spanish for consistency.</p>')],
 faqs=[('Is 017 free?','Yes, it is INCIBE’s free and confidential helpline.'),('What is the AEPD Canal Prioritario?','A fast channel to request removal of sexual or violent content published without consent.')])
C('italy',n='Italy',N='Italy',eu=True,lang=('/it/link-ricorso-meta-instagram-facebook/','Italiano'),
 ans='In Italy, AGCOM is the Digital Services Coordinator and certified ADR Center as a dispute body, the Garante can block intimate images before they are shared, Polizia Postale handles hacking and sextortion, and User Rights and Appeals Centre Europe both work in Italian.',
 cards=[('AGCOM','DSA coordinator.'),('Garante','Revenge porn prevention channel.'),('Polizia Postale','Hacking, sextortion.')],
 secs=[('regulators','Italian bodies',R(('AGCOM','https://www.agcom.it/','Digital Services Coordinator.'),ADR,UR,ACE,('Garante per la protezione dei dati personali','https://www.garanteprivacy.it/','Data complaints, plus a procedure (article 144-bis of the Privacy Code) to stop intimate images being shared without consent.'),('Polizia Postale','https://www.commissariatodips.it/','Online police for hacking, fraud and sextortion.'))),
  ('three-bodies','Three dispute bodies in Italian','<p>Italian users can pick ADR Center (certified by AGCOM), User Rights (certified in Germany, works in Italian) or Appeals Centre Europe. All come after Meta’s own appeal.</p>'),
  ('language','In italiano','<p>See our '+a('/it/link-ricorso-meta-instagram-facebook/','Italian guide to Meta appeal links')+'.</p>')],
 faqs=[('Which dispute body works in Italian?','ADR Center, User Rights and Appeals Centre Europe all communicate in Italian.'),('Can the Garante stop revenge porn?','Yes, through its article 144-bis procedure.')])
C('switzerland',n='Switzerland',N='Switzerland',
 ans='Switzerland is not in the EU, so the Digital Services Act and EU dispute bodies such as Appeals Centre Europe do not cover Swiss users; your levers are the revised Federal Act on Data Protection (in force since September 2023), the FDPIC, and the Federal Office for Cybersecurity for hacking reports.',
 cards=[('No DSA','EU dispute bodies do not apply.'),('revFADP','30 days to answer access requests.'),('NCSC/BACS','Report cyber incidents.')],
 secs=[('regulators','Swiss bodies',R(('FDPIC','https://www.edoeb.admin.ch/','Federal Data Protection and Information Commissioner.'),('Federal Office for Cybersecurity (NCSC)','https://www.ncsc.admin.ch/','Report phishing, hacking and fake support offers.'),('Cantonal police','https://www.suisse-epolice.ch/','Online police reports in many cantons.'))),
  ('fadp','Access rights under the revFADP','<p>Since 1 September 2023, the revised FADP gives you the right to ask a company what personal data it processes about you. The answer is normally due within 30 days. It will not overturn a disable, but it can reveal what Meta holds.</p>'),
  ('no-dsa','What not having the DSA means','<p>Swiss users still get Meta’s internal appeal, but EU out-of-court bodies accept EU users. Do not pay services claiming to file DSA complaints for Swiss accounts.</p>'),
  ('language','Language','<p>Appeal in German, French or Italian, whichever you write best; see the '+a('/de/meta-einspruch-links-instagram-facebook/','German')+' and '+a('/fr/liens-officiels-appel-meta-instagram-facebook/','French')+' guides.</p>')],
 faqs=[('Can I use Appeals Centre Europe from Switzerland?','It accepts disputes from EU countries; Switzerland is not one.'),('How fast must Meta answer a Swiss access request?','Normally within 30 days.')])
C('uae',n='the UAE',N='the UAE',lang=('/ar/rawabit-istinaf-meta/','العربية'),
 ans='In the UAE, hacked or extorted accounts are reported to Dubai Police through the eCrime Hub (UAE Pass login), to Abu Dhabi Police through Aman on 800 2626, or nationwide through the Ministry of Interior’s eCrimes service; Meta’s own appeal is still the only way to reverse a disable.',
 cards=[('eCrime Hub','Dubai Police, UAE Pass.'),('Aman 800 2626','Abu Dhabi Police.'),('Arabic appeals','Accepted.')],
 secs=[('regulators','Where to report in the UAE',R(('Dubai Police eCrime Hub','https://ecrimehub.gov.ae/','Report hacking, account takeover and cyber fraud that happened in Dubai. Log in with UAE Pass and upload screenshots.'),('Abu Dhabi Police: Aman','https://adpolice.gov.ae/en','Confidential reporting service, 800 2626.'),('Ministry of Interior eCrimes service','https://moi.gov.ae/','In the MOI UAE app, for all emirates.'),('My Safe Society (Public Prosecution)','https://www.pp.gov.ae/','App for reporting crimes, including online crimes.'))),
  ('law','The legal background','<p>Federal Decree-Law No. 34 of 2021 on combating rumours and cybercrimes covers hacking, extortion and impersonation, and Federal Decree-Law No. 45 of 2021 is the UAE’s personal data protection law. A police report helps when a hacker used your account for blackmail or fraud.</p>'),
  ('uae-issues','Common UAE situations',ul(['Business accounts for Dubai shops and agencies losing the ad account and Page together.','Accounts flagged after logins from several countries while travelling; appeal from your usual device.','Extortion over private photos: report to the police and do not pay.'])),
  ('language','Arabic or English','<p>Write the appeal in Arabic or English. See our '+a('/ar/rawabit-istinaf-meta/','Arabic guide to Meta appeal links')+'.</p>'),
  ('timing','Time zone','<p>The UAE is on Gulf Standard Time (UTC+4) all year.</p>')],
 faqs=[('Where do I report a hacked Instagram in Dubai?','Dubai Police eCrime Hub at ecrimehub.gov.ae, with UAE Pass.'),('Is there a Meta office I can call in Dubai?','There is no public support line for accounts.')])
C('saudi-arabia',n='Saudi Arabia',N='Saudi Arabia',lang=('/ar/rawabit-istinaf-meta/','العربية'),
 ans='In Saudi Arabia, cybercrime such as hacking, impersonation and blackmail is reported through the Ministry of Interior’s Kollona Amn app, and personal-data complaints under the PDPL go to SDAIA’s National Data Governance Platform with an Absher account; Meta’s appeal remains the route to reverse a disable.',
 cards=[('Kollona Amn','Hacking, blackmail, impersonation.'),('SDAIA','PDPL complaints via Absher.'),('30 days','For data requests.')],
 secs=[('regulators','Where to report in Saudi Arabia',R(('Kollona Amn (Ministry of Interior)','https://my.gov.sa/en/services/398352','Report blackmail, hacking, account theft, impersonation and online fraud. Choose the platform and attach evidence.'),('SDAIA: personal data complaints','https://dgp.sdaia.gov.sa/wps/portal/pdp/services/ReportsComplaints','PDPL complaints through the National Data Governance Platform; needs an Absher account and supporting documents.'))),
  ('pdpl','Your rights under the PDPL','<p>The Personal Data Protection Law gives rights to be informed, to access and get a copy of your data, to correction and to destruction of data no longer needed. Under the implementing regulation, a controller must respond within 30 days, extendable once by 30 days. Complaints should generally be filed within 90 days of the incident.</p>'),
  ('law','Cybercrime','<p>The Anti-Cyber Crime Law covers unauthorised access, blackmail and defamation. Keep the Kollona Amn report number for your hacked-account appeal.</p>'),
  ('language','Arabic','<p>Write the appeal in Arabic if that is clearer for you. See our '+a('/ar/rawabit-istinaf-meta/','Arabic guide')+'.</p>'),
  ('timing','Time zone','<p>Saudi Arabia is on Arabia Standard Time (UTC+3).</p>')],
 faqs=[('Where do I report Instagram blackmail in Saudi Arabia?','Through the Kollona Amn app, under cybercrime.'),('Do I need Absher for a data complaint?','Yes, the SDAIA complaint service requires an Absher account.')])
C('israel',n='Israel',N='Israel',
 ans='In Israel, the National Cyber Directorate’s 119 hotline helps with hacked accounts, Moked 105 handles online harm to children, and the Privacy Protection Authority enforces the Protection of Privacy Law, strengthened by Amendment 13 in August 2025.',
 cards=[('119','Cyber Directorate hotline.'),('105','Child online protection.'),('Amendment 13','Privacy law update, 2025.')],
 secs=[('regulators','Where to report in Israel',R(('Israel National Cyber Directorate: 119','https://www.gov.il/en/departments/israel_national_cyber_directorate','24/7 cyber hotline for hacking and phishing.'),('Moked 105 (gov.il)','https://www.gov.il/','National centre for child online protection.'),('Privacy Protection Authority','https://www.gov.il/en/departments/the_privacy_protection_authority','Regulator for the Protection of Privacy Law.'),('Israel Police','https://www.police.gov.il/','Report fraud and extortion.'))),
  ('privacy','Privacy law','<p>Amendment 13 to the Protection of Privacy Law took effect in August 2025 and expanded the Authority’s enforcement powers. You can request access to personal data held about you.</p>'),
  ('language','Hebrew or Arabic','<p>Meta reviews appeals in Hebrew and Arabic. Write in the language you use most precisely; Arabic speakers can use our '+a('/ar/','Arabic section')+'.</p>')],
 faqs=[('Who helps with a hacked Instagram in Israel?','Call 119, the National Cyber Directorate hotline, and use instagram.com/hacked.')])
C('south-africa',n='South Africa',N='South Africa',
 ans='In South Africa, the Information Regulator enforces POPIA, the Cybercrimes Act 19 of 2020 makes unlawful access and cyber extortion crimes you can report to SAPS, and the Film and Publication Board handles complaints about harmful content.',
 cards=[('Information Regulator','POPIA complaints.'),('Cybercrimes Act','Report to SAPS.'),('SAST','UTC+2.')],
 secs=[('regulators','Where to report in South Africa',R(('Information Regulator','https://inforegulator.org.za/','Complaints under POPIA.'),('SAPS','https://www.saps.gov.za/','Report hacking, fraud and extortion under the Cybercrimes Act.'),('SABRIC','https://www.sabric.co.za/','Banking crime guidance if money left your account.'),('Film and Publication Board','https://www.fpb.org.za/','Complaints about harmful and prohibited content.'))),
  ('popia','POPIA','<p>POPIA gives you a right to ask whether a responsible party holds your personal information and to request corrections. If a request goes nowhere, complain to the Information Regulator.</p>'),
  ('language','Language','<p>Appeal in English unless another official language is clearer for you.</p>')],
 faqs=[('Is hacking an Instagram account a crime in South Africa?','Yes, unlawful access is an offence under the Cybercrimes Act 19 of 2020.')])
C('turkey',n='Turkey',N='Turkey',lang=('/tr/meta-itiraz-linkleri/','Türkçe'),
 ans='In Turkey, Law No. 5651 requires large foreign social networks such as Meta to appoint a local representative and answer applications about personal rights within 48 hours, and under KVKK you must first apply to Meta’s data controller representative and wait up to 30 days before complaining to the Personal Data Protection Authority.',
 cards=[('Law 5651','Local representative, 48 hours.'),('KVKK','Apply first, then complain.'),('İhbar Web','Report illegal content.')],
 secs=[('regulators','Where to report in Turkey',R(('KVKK (Personal Data Protection Authority)','https://www.kvkk.gov.tr/','Complaints after you have applied to the data controller.'),('BTK İhbar Web','https://www.ihbarweb.org.tr/','Report illegal online content.'),('EGM Siber Suçlarla Mücadele','https://www.egm.gov.tr/','Police cybercrime unit for hacking and fraud.'),('USOM','https://www.usom.gov.tr/','National cyber incident response centre.'))),
  ('kvkk','KVKK timing','<p>Apply to Meta’s registered data controller representative first. It has 30 days to respond. If it refuses, answers inadequately or stays silent, you can complain to KVKK within 30 days of learning the response and no later than 60 days after your application.</p>'),
  ('5651','Law 5651','<p>Since the 2020 amendment, social network providers with more than one million daily users in Turkey must have a local representative and respond to individual applications about personal rights within 48 hours. This covers content about you, not account reinstatement.</p>'),
  ('language','Türkçe','<p>Our '+a('/tr/meta-itiraz-linkleri/','Turkish guide to Meta appeal links')+' covers the same routes.</p>')],
 faqs=[('Can I complain to KVKK straight away?','No. Apply to the data controller first and wait for the reply or 30 days.')])
# ---------------- regional pages ----------------
REG={}
def G(slug,**k): REG[slug]=k
G('nordics',n='the Nordic countries',N='Sweden, Denmark, Finland and Norway',merged=['sweden','denmark','finland','norway'],
 ans='Sweden, Denmark and Finland are EU members, so Digital Services Act rights and Appeals Centre Europe apply; Norway is in the EEA but outside the EU, so EU dispute bodies do not cover Norwegian users. Each country has its own data protection authority and police reporting.',
 parts=[('sweden','Sweden','<p>IMY is the data protection authority and PTS the Digital Services Coordinator. Report hacking and fraud to Polisen. EU dispute bodies such as ACE accept Swedish users.</p>',[('IMY','https://www.imy.se/','Data protection authority.'),('PTS','https://www.pts.se/','Digital Services Coordinator.'),('Polisen','https://polisen.se/','Report hacking and online fraud.')]),
  ('denmark','Denmark','<p>Datatilsynet handles data complaints; the police take reports of hacking and fraud. Danish users can use EU dispute bodies after Meta’s appeal.</p>',[('Datatilsynet','https://www.datatilsynet.dk/','Data protection authority.'),('Politi','https://politi.dk/','Report hacking and online fraud.')]),
  ('finland','Finland','<p>Traficom is the Digital Services Coordinator and hosts the National Cyber Security Centre; the Data Protection Ombudsman handles data complaints. Appeal in Finnish or Swedish.</p>',[('Traficom','https://www.traficom.fi/','Digital Services Coordinator.'),('National Cyber Security Centre','https://www.kyberturvallisuuskeskus.fi/','Report phishing and hacking.'),('Data Protection Ombudsman','https://tietosuoja.fi/','Data protection authority.')]),
  ('norway','Norway','<p>Norway applies the GDPR through the EEA Agreement, so Datatilsynet handles data complaints, but EU dispute bodies accept EU users only. Slettmeg.no gives free help with unwanted content about you online.</p>',[('Datatilsynet','https://www.datatilsynet.no/','Data protection authority.'),('Slettmeg.no','https://slettmeg.no/','Free help removing unwanted online content.'),('Politiet','https://www.politiet.no/','Report hacking and online fraud.')])])
G('other-eu-countries',n='other EU countries',N='Austria, Belgium, Luxembourg, Portugal, Poland, Czechia and Greece',merged=['austria','belgium','luxembourg','portugal','poland','czech-republic','greece'],
 ans='Every EU country gets the same Digital Services Act rights: a statement of reasons, Meta’s internal appeal and then a certified dispute body such as Appeals Centre Europe. What differs is the local data authority, police route and the languages each dispute body works in.',
 parts=[('austria','Austria','<p>KommAustria (with RTR) is the Digital Services Coordinator, and RTR’s media department is itself a certified out-of-court dispute body, working in German. The Datenschutzbehörde handles data complaints.</p>',[('RTR','https://www.rtr.at/','Digital Services Coordinator support and a certified dispute body.'),('Datenschutzbehörde','https://www.dsb.gv.at/','Data protection authority.'),('Watchlist Internet','https://www.watchlist-internet.at/','Warnings about online scams and fake support.')]),
  ('belgium','Belgium','<p>BIPT is the Digital Services Coordinator. Forward suspicious messages to suspect@safeonweb.be. Appeal in French, Dutch or German.</p>',[('BIPT','https://www.bipt.be/','Digital Services Coordinator.'),('Data Protection Authority','https://www.dataprotectionauthority.be/','Data protection complaints.'),('Safeonweb','https://safeonweb.be/','Official cybersecurity advice and phishing reporting.')]),
  ('luxembourg','Luxembourg','<p>The CNPD handles data complaints. BEE SECURE runs the national helpline and stopline for online safety.</p>',[('CNPD','https://cnpd.public.lu/','Data protection authority.'),('BEE SECURE','https://www.bee-secure.lu/','Online safety helpline and stopline.')]),
  ('portugal','Portugal','<p>ANACOM is the Digital Services Coordinator and CNPD the data authority. ADR Center works in Portuguese.</p>',[('ANACOM','https://www.anacom.pt/','Digital Services Coordinator.'),('CNPD','https://www.cnpd.pt/','Data protection authority.'),('Centro Nacional de Cibersegurança','https://www.cncs.gov.pt/','National cybersecurity centre.')]),
  ('poland','Poland','<p>UODO handles data complaints and CERT Polska takes incident reports. Appeals Centre Europe communicates in Polish.</p>',[('UODO','https://uodo.gov.pl/','Data protection authority.'),('CERT Polska','https://incydent.cert.pl/','Report phishing and hacking.')]),
  ('czech-republic','Czechia','<p>ÚOOÚ is the data authority; report hacking to the Police of the Czech Republic.</p>',[('ÚOOÚ','https://uoou.gov.cz/','Data protection authority.'),('NÚKIB','https://nukib.gov.cz/','National cyber and information security agency.'),('Policie ČR','https://www.policie.cz/','Report online crime.')]),
  ('greece','Greece','<p>The Hellenic DPA handles data complaints and the Hellenic Police Cyber Crime Division takes reports. ADR Center works in Greek.</p>',[('Hellenic Data Protection Authority','https://www.dpa.gr/','Data protection authority.'),('Cyber Crime Division','https://www.astynomia.gr/','Hellenic Police cybercrime unit.')])],
 extra=[('ods','Dispute bodies and languages',R(ACE,UR,ADR,('RTR-GmbH, Fachbereich Medien','https://www.rtr.at/','Certified by KommAustria; German.')))])
G('gulf',n='Qatar, Kuwait, Bahrain, Oman and Iraq',N='Qatar, Kuwait, Bahrain, Oman and Iraq',merged=['qatar','kuwait','bahrain','oman','iraq'],lang=('/ar/rawabit-istinaf-meta/','العربية'),
 ans='Across the Gulf, Meta’s appeal routes are identical, but hacking and blackmail are reported to each country’s interior ministry: Metrash in Qatar, the Electronic and Cyber Crime Combating Department in Kuwait, hotline 992 in Bahrain and the Royal Oman Police in Oman.',
 parts=[('qatar','Qatar','<p>Report cybercrime in Metrash under Security Complaint, then Cyber Crime, or contact the Economic and Cyber Crimes Combating Department. Qatar’s personal data law is Law No. 13 of 2016.</p>',[('Ministry of Interior (Metrash)','https://portal.moi.gov.qa/','Cybercrime reports through Metrash.')]),
  ('kuwait','Kuwait','<p>The Ministry of Interior’s Electronic and Cyber Crime Combating Department takes reports of hacking, blackmail and fraud.</p>',[('Ministry of Interior: Cyber Crime','https://moi.gov.kw/main/sections/cyber-crime?culture=en','Electronic and Cyber Crime Combating Department.')]),
  ('bahrain','Bahrain','<p>Call 992, the General Directorate of Anti-Corruption and Economic and Electronic Security. Bahrain’s data law is Law No. 30 of 2018.</p>',[('Anti-Cyber Crime Directorate','https://www.acees.gov.bh/cyber-crime','Hotline 992.')]),
  ('oman','Oman','<p>Complaints under the Personal Data Protection Law (Royal Decree 6/2022) go to the Ministry of Transport, Communications and IT; report hacking to the Royal Oman Police.</p>',[('MTCIT: personal data protection','https://www.mtcit.gov.om/','PDPL complaints.'),('Royal Oman Police','https://www.rop.gov.om/','Report cybercrime.')]),
  ('iraq','Iraq','<p>We could not verify a dedicated national data-protection regulator to escalate to. Use Meta’s routes, and report extortion to the police.</p>',[])])
G('east-asia',n='Japan, South Korea, Hong Kong and Taiwan',N='Japan, South Korea, Hong Kong and Taiwan',merged=['japan','south-korea','hong-kong','taiwan'],
 ans='In Japan, Meta is a designated large-scale platform under the Information Distribution Platform Act and must usually answer removal requests within seven days; South Korea has the KISA 118 hotline; Hong Kong’s PCPD can act against doxxing; and Taiwan runs the 165 anti-fraud hotline.',
 parts=[('japan','Japan','<p>On 30 April 2025, Japan designated Meta Platforms (Facebook, Instagram, Threads) under the Information Distribution Platform Act. For removal requests about rights infringement, Meta must generally notify you within seven days whether it acted. The Personal Information Protection Commission handles data complaints.</p>',[('Personal Information Protection Commission','https://www.ppc.go.jp/','Data protection authority.'),('MIC: Information Distribution Platform Act','https://www.soumu.go.jp/main_sosiki/joho_tsusin/eng/pressrelease/2025/4/30_3.html','Designation of large platforms.')]),
  ('south-korea','South Korea','<p>KISA’s 118 hotline handles personal data and hacking reports; the Personal Information Protection Commission enforces PIPA; the National Police cyber bureau takes crime reports.</p>',[('KISA: 118','https://www.kisa.or.kr/','Privacy and hacking hotline.'),('PIPC','https://www.pipc.go.kr/','Data protection authority.'),('ECRM (Police)','https://ecrm.police.go.kr/','Online crime reports.')]),
  ('hong-kong','Hong Kong','<p>The PCPD enforces the PDPO; since 2021 doxxing is an offence and the PCPD can direct removal of doxxing content. Check suspicious contacts with Scameter and call 18222 for scams.</p>',[('PCPD','https://www.pcpd.org.hk/','Privacy Commissioner.'),('Police e-Report Centre','https://www.police.gov.hk/ppp_en/','Report fraud and hacking.')]),
  ('taiwan','Taiwan','<p>Call 165 for fraud. The Fraud Crime Hazard Prevention Act (2024) requires online ad platforms to verify advertisers, which affects ad accounts.</p>',[('165 Anti-Fraud','https://165.npa.gov.tw/','National anti-fraud hotline and site.')])])
G('southeast-asia',n='Singapore, Malaysia and the Philippines',N='Singapore, Malaysia and the Philippines',merged=['singapore','malaysia','philippines'],
 ans='In Singapore, the Online Safety Commission has handled harassment, doxxing, stalking and intimate-image abuse since 29 June 2026; Malaysia’s National Scam Response Centre is on 997; and the Philippines’ CICC runs the 1326 hotline.',
 parts=[('singapore','Singapore','<p>The Online Safety Commission began operations on 29 June 2026 under the Online Safety (Relief and Accountability) Act 2025. It does not restore accounts. The PDPC enforces the PDPA, and the ScamShield helpline is 1799.</p>',[('Online Safety Commission','https://onlinesafety.mlaw.gov.sg/getting-help/reporting-to-the-osc/','Reports of online harms.'),('PDPC','https://www.pdpc.gov.sg/','Data protection.'),('ScamShield','https://www.scamshield.gov.sg/','Check and report scams.')]),
  ('malaysia','Malaysia','<p>Call 997 (National Scam Response Centre) quickly if money moved. Cyber999 takes incident reports; the PDP Commissioner handles data complaints.</p>',[('Cyber999','https://www.mycert.org.my/','Report hacking and phishing.'),('PDP Commissioner','https://www.pdp.gov.my/','Data protection.')]),
  ('philippines','Philippines','<p>The CICC hotline 1326 and PNP Anti-Cybercrime Group handle hacking and scams; the NPC handles complaints under the Data Privacy Act 2012.</p>',[('CICC','https://cicc.gov.ph/','Hotline 1326.'),('National Privacy Commission','https://privacy.gov.ph/','Data privacy complaints.')])])
REDIRECT={'meta-appeal-links-india':'/meta-appeal-links-and-forms-directory/','meta-appeal-links-pakistan':'/meta-appeal-links-and-forms-directory/','meta-appeal-links-nigeria':'/meta-appeal-links-and-forms-directory/'}
for g,k in REG.items():
    for m in k['merged']: REDIRECT[f'meta-appeal-links-{m}']=f'/meta-appeal-links-{g}/'
PAGES=[]
def page(slug,n,N,ans,cards,secs,faqs,eu=False,lang=None):
    s=[('official','The Meta routes',OFF)]+secs
    if eu and not any(x[0]=='dsa' for x in secs): s.append(('dsa','EU rights in one line','<p>As an EU user you get a statement of reasons, Meta’s internal appeal and then a certified dispute body. See '+a('/dsa-appeal-right-instagram-facebook/','DSA appeal rights')+'.</p>'))
    PAGES.append(P(slug=f'meta-appeal-links-{slug}',svc='ig',offer=False,crumb=('Meta appeal links','/meta-appeal-links-and-forms-directory/'),navrel=NAV,
      title=f'Meta Appeal Links for {N[0].upper()+N[1:]} (2026): Local Regulators, Reporting and Rights',short=f'Meta appeal links {n}',
      desc=(ans[:150].rsplit(' ',1)[0]+'…'),h1=f'Meta appeal links for {n}.',lede='What is specific to '+n+': regulators, reporting lines and rights.',
      answer='<strong>'+ans+'</strong> If the official route fails, Unbanz handles Instagram ($800) and Facebook ($900) cases, paid upfront with a 100% refund if it fails.',
      cards=cards,sections=s,faqs=faqs,related=[('/meta-appeal-links-and-forms-directory/','Meta appeal links directory'),('/account-recovery-by-country/','Account recovery by country')]))
for slug,k in D.items(): page(slug,k['n'],k['N'],k['ans'],k['cards'],k['secs'],k['faqs'],k.get('eu',False),k.get('lang'))
for g,k in REG.items():
    secs=[(sl,nm,txt+(R(*rows) if rows else '')) for sl,nm,txt,rows in k['parts']]+k.get('extra',[])
    if k.get('lang'): secs.append(('language','Arabic','<p>See our '+a(k['lang'][0],'Arabic guide to Meta appeal links')+'.</p>'))
    cards=[(nm,re.sub(r'<[^>]+>','',txt).split('. ')[0][:90]+'.') for sl,nm,txt,_ in k['parts'][:3]]
    faqs=[(f'Why are {k["N"]} on one page?','The Meta routes are identical; only the local bodies differ, so each country has its own section.')]
    page(g,k['n'],k['N'],k['ans'],cards,secs,faqs,g in('nordics','other-eu-countries'))
# ---------------- contact pages ----------------
CH=table([('Disabled or suspended','Appeal from the login notice or Accounts Center'),('Hacked','instagram.com/hacked or facebook.com/hacked'),('Meta Verified subscriber','Chat in the app'),('Advertiser','Business Support Home')])
CT={'usa':('the US','the USA','Meta has no account support phone line in the US, so contact runs through the app; outside it, the useful US contacts are the FTC for fake support numbers and IC3 if a hacker took money.',[('scam-numbers','Fake “Meta support” numbers in the US','<p>US search results and comment sections are full of “Instagram support” phone numbers. None are Meta. Report them at '+ext('https://reportfraud.ftc.gov/')+'. If someone already took money, file with '+ext('https://www.ic3.gov/')+'.</p>'),('ccpa','Contacting Meta about your data','<p>California residents can send a CCPA request to know what data Meta holds; it is a written channel that gets a formal reply, unlike the help center.</p>')]),
 'uk':('the UK','the UK','Meta has no UK account support number; the formal written channel UK users have is a subject access request under the UK GDPR, with a one-month deadline, and fake support offers go to Report Fraud.',[('sar','A written channel with a deadline','<p>A subject access request must be answered within one month (extendable by two). If Meta ignores it, complain to the '+ext('https://ico.org.uk/make-a-complaint/')+'.</p>'),('scam-numbers','Fake support in the UK','<p>Report fake “Meta agents” to '+ext('https://www.reportfraud.police.uk/')+' (0300 123 2040), which replaced Action Fraud on 4 December 2025. In Scotland, call 101.</p>')]),
 'canada':('Canada','Canada','Meta has no Canadian support line; the formal written channel is a PIPEDA access request, which must normally be answered within 30 days, and fake support offers go to the Canadian Anti-Fraud Centre.',[('pipeda','A written channel with a deadline','<p>Send Meta a PIPEDA access request. If it is ignored after 30 days, complain to the '+ext('https://www.priv.gc.ca/en/report-a-concern/')+'. Quebec residents can also contact the '+ext('https://www.cai.gouv.qc.ca/')+'.</p>'),('scam-numbers','Fake support in Canada','<p>Report fake agents to the '+ext('https://antifraudcentre-centreantifraude.ca/')+' or 1-888-495-8501. Appeal in English or French.</p>')]),
 'australia':('Australia','Australia','Meta has no Australian support line; the escalation contacts are eSafety for serious abuse after you report to Meta, and the OAIC for privacy once Meta has had 30 days to reply.',[('esafety','Contacting eSafety','<p>Report to Meta first, keep the reference, then use '+ext('https://www.esafety.gov.au/report')+'. eSafety handles harmful content, not disables.</p>'),('under16','Under-16 deactivations','<p>Since 10 December 2025, accounts of Australians under 16 are being removed. If you are 16 or over and were flagged, use the age-check option (video selfie or ID) in the notice.</p>'),('scam-numbers','Fake support','<p>Report fake agents to '+ext('https://www.scamwatch.gov.au/')+'.</p>')]),
 'uae':('the UAE','the UAE','Meta has no UAE support line; if your account was hacked or used for blackmail, the contacts that act are Dubai Police’s eCrime Hub, Abu Dhabi Police Aman (800 2626) and the MOI eCrimes service.',[('police','Police contacts','<p>Dubai: '+ext('https://ecrimehub.gov.ae/')+' with UAE Pass. Abu Dhabi: Aman, 800 2626. Other emirates: eCrimes in the MOI UAE app. Emergencies: 999.</p>'),('arabic','بالعربية','<p>'+a('/ar/tawasul-maa-meta/','التواصل مع دعم ميتا')+'</p>')]),
 'saudi-arabia':('Saudi Arabia','Saudi Arabia','Meta has no Saudi support line; for hacking, impersonation or blackmail use Kollona Amn, and for personal data complaints SDAIA’s platform with Absher.',[('police','Government contacts','<p>Kollona Amn app for cybercrime ('+ext('https://my.gov.sa/en/services/398352')+'). SDAIA personal data complaints: '+ext('https://dgp.sdaia.gov.sa/wps/portal/pdp/services/ReportsComplaints')+'.</p>'),('arabic','بالعربية','<p>'+a('/ar/tawasul-maa-meta/','التواصل مع دعم ميتا')+'</p>')])}
for slug,(n,N,ans,secs) in CT.items():
    PAGES.append(P(slug=f'how-to-contact-meta-support-{slug}',svc='ig',offer=False,crumb=('How to contact Meta','/how-to-contact-meta-about-a-disabled-account/'),navrel=NAV,
     title=f'How to Contact Meta Support in {N[0].upper()+N[1:]} (2026): Instagram & Facebook',short=f'Contact Meta support {n}',
     desc=ans[:150].rsplit(' ',1)[0]+'…',h1=f'How to contact Meta support in {n}.',lede='Which contacts actually respond, and which are scams.',
     answer='<strong>'+ans+'</strong>',cards=[('No phone line','Numbers claiming to be Meta are scams.'),('In-app first','Appeal from the notice.'),('Local contacts','Below.')],
     sections=[('channels','Meta channels',CH)]+secs+[('appeal-links','Appeal links for '+n,'<p>'+a(f'/meta-appeal-links-{slug}/',f'Meta appeal links for {n}')+'</p>')],
     faqs=[(f'Is there a Meta phone number in {n}?','No public account support number.')],related=[('/how-to-contact-meta-about-a-disabled-account/','How to contact Meta'),(f'/meta-appeal-links-{slug}/',f'Meta appeal links {n}')]))
# extra unique contact content
XC={'usa':[('us-business','US advertisers and creators','<p>US advertisers spending through Ads Manager can open a support case in Business Support Home or Meta’s Business Help Center; this is the only route where a human chat is commonly offered without a subscription. Creators in the Partner Program sometimes see a dedicated support entry in Professional Dashboard. Neither channel can reverse a personal account disable, but both can escalate ad account and Page restrictions.</p>'),('us-legal','Legal requests','<p>Law enforcement requests go through Meta’s records portal, not to users. If you have a lawyer, they write to Meta Platforms, Inc. in Menlo Park; that is a legal route, not support, and slow.</p>'),('us-after','After you make contact','<p>Expect automated replies first. Keep every case number. Most US cases we see that were reversed came through the in-app appeal or an ad account review, not through email.</p>')],
'uk':[('uk-business','UK businesses','<p>UK advertisers can request support in Business Support Home. If a hacker ran ads on your card, tell your bank and report it to Report Fraud; card disputes are often faster than waiting for Meta to refund ad spend.</p>'),('uk-osa','Complaints under the Online Safety Act','<p>Instagram and Facebook must offer UK users a way to complain, including about content wrongly taken down. Use the in-app report and appeal tools, and keep screenshots. Ofcom does not take individual cases but does publish guidance on what platforms must do.</p>'),('uk-after','After you make contact','<p>If a subject access request comes back incomplete, reply to Meta once citing the missing items before going to the ICO.</p>')],
'canada':[('ca-business','Canadian advertisers','<p>Advertisers can request a review or chat in Business Support Home. If a hacked ad account charged your card, contact your bank and report the fraud; keep the Anti-Fraud Centre reference for your appeal.</p>'),('ca-quebec','Quebec residents','<p>Law 25 strengthened Quebec privacy rights, including transparency about automated decisions. You can ask Meta, in French, for the personal information it holds, and complain to the Commission d’accès à l’information if it does not reply.</p>'),('ca-after','After you make contact','<p>Keep a dated log of each request. Responses to access requests usually come by email from Meta’s privacy team.</p>')],
'australia':[('au-business','Australian advertisers','<p>Ad accounts and Pages are reviewed in Business Support Home. If a hacked account ran ads on your card, call your bank first and report to ReportCyber; IDCARE can help if your identity was used.</p>'),('au-privacy','Privacy requests','<p>Under the Australian Privacy Principles you can ask Meta for access to personal information it holds about you. If you get no proper answer in 30 days, complain to the OAIC.</p>'),('au-after','After you make contact','<p>eSafety will ask for the Meta report reference, so screenshot the confirmation the moment you report.</p>')],
'uae':[('uae-business','UAE businesses','<p>Shops and agencies in Dubai and Abu Dhabi often lose the ad account, Page and Instagram together when one admin is hacked. Remove unknown admins in Business Settings as soon as you regain access, and request reviews in Business Support Home.</p>'),('uae-extortion','Blackmail and extortion','<p>If someone threatens to publish private images or messages, do not pay or negotiate. Save the messages, report to the police channel for your emirate, and report the account in the app.</p>'),('uae-after','After you make contact','<p>Keep the police report number and mention it in the hacked-account form. Appeals can be written in Arabic or English.</p>')],
'saudi-arabia':[('sa-business','Saudi businesses','<p>Saudi stores selling through Instagram and Facebook often rely on one admin account. Add a second trusted admin to the Business Portfolio, and use Business Support Home for ad account and Page reviews.</p>'),('sa-blackmail','Blackmail','<p>Online blackmail is covered by the Anti-Cyber Crime Law. Report it in Kollona Amn with screenshots, and do not pay. Then report the account to Meta.</p>'),('sa-after','After you make contact','<p>Kollona Amn reports are processed in about 10 working days according to the national portal. Keep the report reference for your appeal.</p>')]}
for p in PAGES:
    s=p['slug'].replace('how-to-contact-meta-support-','')
    if p['slug'].startswith('how-to-contact') and s in XC:
        i=[x[0] for x in p['sections']].index('appeal-links'); p['sections'][i:i]=XC[s]
